mod audio;mod game;mod video;use game::Game;
fn main(){let mut out=vec![];for (typ,handler,variant) in [(24,0x8e1f,0),(146,0x957c,1),(49,0xafd6,0),(64,0xa7a9,0),(10,0x881a,0),(35,0xade5,0),(36,0xae7a,0),(66,0xa9d2,0),(74,0xb6b2,0),(71,0xb4a2,0),(75,0x9bde,0),(79,0x9e0f,0),(72,0xb5c7,56),(72,0xb5c7,68),(76,0x9d71,0),(77,0x9de6,0)]{let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x27]=6;g.memory[0x530]=1;g.memory[0x5b0]=80;g.memory[0x570]=160;g.memory[0x720]=typ;g.memory[0x710]=80;g.memory[0x560]=80;g.memory[0x690]=variant;g.memory[0x3b]=6;g.memory[0xd5]=1;g.memory[0x740]=if typ==10{138}else if typ==74{63}else if typ==75{255}else if typ==79{192}else{160};if typ==72 {g.memory[0x6c0]=if variant==68{8}else{12};}let mut samples=vec![];for tick in 0..700{g.actor_call(handler,0).unwrap();let mut shots=vec![];for j in 1..16{if g.memory[0x720+j]!=0{shots.push(g.memory[0x720+j]);g.memory[0x720+j]=0;}}samples.push(serde_json::json!({"tick":tick,"sprite":g.memory[0x500],"state":g.memory[0x520],"flags":g.memory[0x730],"health":g.memory[0x740],"timer":g.memory[0x660],"fire_timer":g.memory[0x670],"direction":g.memory[0x6c0],"flips":g.memory[0x6a],"x":g.memory[0x710] as f32+g.memory[0x6f0] as i8 as f32*256.+g.memory[0x5c0] as f32/256.,"y":g.memory[0x560]as f32+g.memory[0x700]as i8 as f32*256.+g.memory[0x580]as f32/256.,"shots":shots}));}out.push(serde_json::json!({"source_type":typ,"samples":samples}));}println!("{}",serde_json::to_string(&out).unwrap());}
